import { describe, expect, test } from "bun:test"

import { generatedNote, jsonText, MODULE_COMMENT } from "../src/instructions/generated.ts"

const strip = (text: string) => text.replace(MODULE_COMMENT, "")

describe("the generated file helpers", () => {
  test("write JSON with a two-space indent and a final newline", () => {
    expect(jsonText({ a: [1] })).toBe('{\n  "a": [\n    1\n  ]\n}\n')
  })

  test("name the builder and the source in the note", () => {
    expect(generatedNote("pkg/build.ts", "src/a.md")).toBe(
      "Generated by pkg/build.ts from src/a.md; edit the source and rebuild.",
    )
  })

  test("drop Bun's module comments, whether or not the path holds a space", () => {
    const text = [
      "// node_modules/effect/dist/index.js",
      "var a = 1",
      "// /home/my repo/packages/runtime/src/main.ts",
      "var b = 2",
      "// C:\\my repo\\src\\main.mts",
      "var c = 3",
      "// data/skill notes.md",
    ].join("\n")
    expect(strip(`${text}\n`)).toBe("var a = 1\nvar b = 2\nvar c = 3\n")
  })

  test("keep a prose comment that merely ends in a file extension", () => {
    expect(strip("// see the notes in main.ts\nvar a = 1\n")).toBe(
      "// see the notes in main.ts\nvar a = 1\n",
    )
  })
})
